def _scan_uv_lock(path: pathlib.Path) -> list[str]:
    """Return tracked packages found in a `uv.lock` file, with exact versions."""
    tracked = {_normalize_package_name(pkg): pkg for pkg in TRACKED_PACKAGES}
    content = _read_capped(path)

    versions: dict[str, str] = {}
    current_name: str | None = None
    for raw_line in content.splitlines():
        line = raw_line.strip()
        if line == "[[package]]":
            current_name = None
            continue
        name_match = re.match(r'name\s*=\s*"([^"]+)"', line)
        if name_match:
            current_name = name_match.group(1)
            continue
        version_match = re.match(r'version\s*=\s*"([^"]+)"', line)
        if version_match and current_name is not None:
            versions[_normalize_package_name(current_name)] = version_match.group(1)
            current_name = None

    results: list[str] = []
    for normalized, display_name in tracked.items():
        if normalized in versions:
            results.append(f"{display_name}:{versions[normalized]}")
    return results


