def _scan_requirements(path: pathlib.Path) -> list[str]:
    """Return tracked packages listed in a `requirements.txt` file."""
    content = _read_capped(path)
    return _match_requirements(content.splitlines())


def _scan_directory(directory: pathlib.Path) -> list[str]:
    """Scan a single dependency directory for tracked packages.

