    The first source that yields a match wins.
    """
    uv_lock = directory / "uv.lock"
    if uv_lock.is_file():
        matches = _scan_uv_lock(uv_lock)
        if matches:
            return matches

    pyproject = directory / "pyproject.toml"
    if pyproject.is_file():
        matches = _scan_pyproject(pyproject)
        if matches:
            return matches

    requirements = directory / "requirements.txt"
    if requirements.is_file():
        matches = _scan_requirements(requirements)
        if matches:
            return matches

    return []


